function checkRepeat(map, key, wordInfo)
{
    if (map.has(key))
        map.get(key).push(wordInfo);
    else
        map.set(key, [wordInfo]);
}

for (const dict of Object.values(dictionary))
{
    const languageRepeats = new Map();

    for (let i = 0; i < dict.length; i++)
    {
        const wordInfo = dict[i];
        let englishWord = wordInfo[0];
        let languageWord = wordInfo[1];

        checkRepeat(languageRepeats, englishWord, wordInfo);
    }

    for (let repeat of languageRepeats.values())
    {
        if (repeat.length <= 1)
            continue;

        for (let i = 0; i < repeat.length; i++)
        {
            const wordInfo = repeat[i];
            // wordInfo[1] += ` (${wordInfo[2]})`;
        }
        console.log(repeat);
    }
}

export let currentDictionary = undefined;
export let currentLanguageName = undefined;

export function setCurrentDictionary(key)
{
    currentDictionary = dictionary[key];
    currentLanguageName = key[0].toUpperCase() + key.slice(1);
}

export default dictionary;